===== EnsureUniqueIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Consolidated duplicate detection for create-owner: rejects a request whose whole derived
 * {@code identityKey} equals that of an existing owner, responding 409 via
 * {@link DuplicateIdentityException}.
 *
 * <p>The key (see {@link Owner#getIdentityKey()}) is
 * {@code normalizedTelephone|email|householdId}, so the former separate telephone, email and
 * household checks are now a single full-key comparison. Because the telephone is part of the
 * key, two members of the same household (same {@code householdId}) with different telephones
 * have different identity keys and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link AssignHousehold} (so the built owner already carries its
 * {@code householdId}, if any) and before {@link SaveOwner} persists anything. The new owner
 * is not yet in the repository, so it is never compared against itself.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = owner.getIdentityKey();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner no longer blocks a duplicate
            }
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of
 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the value is derived
 * purely from the (last name, postcode) pair, every owner sharing that pair computes the
 * same identifier automatically — the household is keyed on the pair, not created by an
 * explicit opt-in.
 *
 * <p>The last name is normalized (compared case-insensitively with collapsed whitespace)
 * before hashing; the postcode is used verbatim, treated as empty when absent. So two
 * owners with the same last name and postcode always share a household, regardless of
 * creation order or the {@code sharesHousehold} flag (which now only bypasses the
 * household-duplicate block — see {@link EnsureUniqueHousehold}).
 *
 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
 * {@link EnsureUniqueHousehold}/{@link SaveOwner}; it mutates the built owner in place
 * (see {@code @Val} semantics). The computed id feeds duplicate detection (via the
 * {@code identityKey}) and the household-size count.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        String lastName = normalize(owner.getLastName());
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        owner.setHouseholdId(householdId(lastName, postcode));
    }

    /** Deterministic 12-char hex id over the normalized last name and postcode. */
    private static String householdId(String lastName, String postcode) {
        return sha256hex(lastName + "|" + postcode).substring(0, 12);
    }

    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.HouseholdDuplicateException;

/**
 * Rejects a create-owner request that would join an existing owner's household — the same
 * computed {@code householdId} (derived from last name and postcode by
 * {@link AssignHousehold}) — responding 409 via {@link HouseholdDuplicateException}.
 *
 * <p>The household is keyed on {@code (lastName, postcode)}, so a second owner sharing
 * that pair is the same household. Two things bypass this block: setting
 * {@code sharesHousehold: true} (a <em>declared</em> household member, which is also not
 * flagged as a possible duplicate — see {@link AssignPossibleDuplicate}), and supplying a
 * distinct {@code email}. An email is part of the owner's {@code identityKey}, so an owner
 * that provides one is a distinguishable individual rather than an accidental re-registration
 * and may join the household. Either way a full-identity duplicate is still caught afterwards
 * by {@link EnsureUniqueIdentity}, so an owner that duplicates an existing owner's whole
 * {@code identityKey} — email and all — is still rejected.
 *
 * <p>Runs after {@link AssignHousehold} (so the built owner already carries its computed
 * {@code householdId}) and before {@link EnsureUniqueIdentity}/{@link SaveOwner}. The new
 * owner is not yet in the repository, so it is never compared against itself.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
            OwnerRepository ownerRepository) throws HouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared member bypasses the household-duplicate block
        }
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            return; // a distinct email identifies the owner; not a household duplicate
        }
        String householdId = owner.getHouseholdId();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner no longer blocks a household duplicate
            }
            if (householdId.equals(existing.getHouseholdId())) {
                throw new HouseholdDuplicateException(householdId);
            }
        }
    }
}
===== AssignPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Flags a soft (non-hard) duplicate on the owner being created.
 *
 * <p>A hard duplicate — an existing owner with the same whole {@code identityKey} — has
 * already been rejected with 409 by {@link EnsureUniqueIdentity}. The soft-match key
 * (same {@code lastName}, compared case-insensitively, and same {@code postcode}, with a
 * <em>different</em> telephone) is now exactly the household key: a non-declared owner
 * sharing it has already been rejected as a household duplicate by
 * {@link EnsureUniqueHousehold}, so the only owner that reaches this step with such a
 * match is a <em>declared</em> household member ({@code sharesHousehold: true}). A
 * declared member is not a suspected duplicate, so it is never flagged.
 *
 * <p>For any other owner the soft match, when present, still sets {@code possibleDuplicate}
 * true and {@code possibleDuplicateOf} to the matching owner's id (the lowest id when
 * several match, for determinism); otherwise {@code possibleDuplicate} is false and
 * {@code possibleDuplicateOf} is absent.
 *
 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link SaveOwner} in the
 * {@code POST /api/owners} pipeline, so the new owner is not yet persisted and is never
 * compared against itself; the flags are persisted with the new owner and returned by
 * later reads. It mutates the built {@link Owner} in place (see {@code @Val} semantics).
 */
public class AssignPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
            OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();
        if (postcode == null) {
            return;
        }
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner is not a possible-duplicate match
            }
            if (equalsIgnoreCase(lastName, existing.getLastName())
                    && postcode.equals(existing.getPostcode())
                    && !equals(telephone, existing.getTelephone())
                    && (match == null || existing.getId() < match.getId())) {
                match = existing;
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    private static boolean equals(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

