9	/**
10	 * Rejects a create-owner request that would join an existing owner's household — the same
11	 * computed {@code householdId} (derived from last name and postcode by
12	 * {@link AssignHousehold}) — responding 409 via {@link HouseholdDuplicateException}.
13	 *
14	 * <p>The household is keyed on {@code (lastName, postcode)}, so a second owner sharing
15	 * that pair is the same household. Two things bypass this block: setting
16	 * {@code sharesHousehold: true} (a <em>declared</em> household member, which is also not
17	 * flagged as a possible duplicate — see {@link AssignPossibleDuplicate}), and supplying a
18	 * distinct {@code email}. An email is part of the owner's {@code identityKey}, so an owner
19	 * that provides one is a distinguishable individual rather than an accidental re-registration
20	 * and may join the household. Either way a full-identity duplicate is still caught afterwards
21	 * by {@link EnsureUniqueIdentity}, so an owner that duplicates an existing owner's whole
22	 * {@code identityKey} — email and all — is still rejected.
23	 *
24	 * <p>Runs after {@link AssignHousehold} (so the built owner already carries its computed
25	 * {@code householdId}) and before {@link EnsureUniqueIdentity}/{@link SaveOwner}. The new
26	 * owner is not yet in the repository, so it is never compared against itself.
27	 */
28	public class EnsureUniqueHousehold {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
31	            OwnerRepository ownerRepository) throws HouseholdDuplicateException {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // declared member bypasses the household-duplicate block
34	        }
35	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
36	            return; // a distinct email identifies the owner; not a household duplicate
37	        }
38	        String householdId = owner.getHouseholdId();
39	        for (Owner existing : ownerRepository.findAll()) {
40	            if (existing.isDeleted()) {
41	                continue; // a soft-deleted owner no longer blocks a household duplicate
42	            }
43	            if (householdId.equals(existing.getHouseholdId())) {
44	                throw new HouseholdDuplicateException(householdId);
45	            }
46	        }
47	    }
48	}
