1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (non-hard) duplicate on the owner being created.
10	 *
11	 * <p>A hard duplicate — an existing owner with the same whole {@code identityKey} — has
12	 * already been rejected with 409 by {@link EnsureUniqueIdentity}. The soft-match key
13	 * (same {@code lastName}, compared case-insensitively, and same {@code postcode}, with a
14	 * <em>different</em> telephone) is now exactly the household key: a non-declared owner
15	 * sharing it has already been rejected as a household duplicate by
16	 * {@link EnsureUniqueHousehold}, so the only owner that reaches this step with such a
17	 * match is a <em>declared</em> household member ({@code sharesHousehold: true}). A
18	 * declared member is not a suspected duplicate, so it is never flagged.
19	 *
20	 * <p>For any other owner the soft match, when present, still sets {@code possibleDuplicate}
21	 * true and {@code possibleDuplicateOf} to the matching owner's id (the lowest id when
22	 * several match, for determinism); otherwise {@code possibleDuplicate} is false and
23	 * {@code possibleDuplicateOf} is absent.
24	 *
25	 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link SaveOwner} in the
26	 * {@code POST /api/owners} pipeline, so the new owner is not yet persisted and is never
27	 * compared against itself; the flags are persisted with the new owner and returned by
28	 * later reads. It mutates the built {@link Owner} in place (see {@code @Val} semantics).
29	 */
30	public class AssignPossibleDuplicate {
31	
32	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
33	            OwnerRepository ownerRepository) {
34	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
35	            return; // a declared household member is not a suspected duplicate
36	        }
37	        String lastName = owner.getLastName();
38	        String postcode = owner.getPostcode();
39	        String telephone = owner.getTelephone();
40	        if (postcode == null) {
41	            return;
42	        }
43	        Owner match = null;
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (existing.isDeleted()) {
46	                continue; // a soft-deleted owner is not a possible-duplicate match
47	            }
48	            if (equalsIgnoreCase(lastName, existing.getLastName())
49	                    && postcode.equals(existing.getPostcode())
50	                    && !equals(telephone, existing.getTelephone())
51	                    && (match == null || existing.getId() < match.getId())) {
52	                match = existing;
53	            }
54	        }
55	        if (match != null) {
56	            owner.setPossibleDuplicate(true);
57	            owner.setPossibleDuplicateOf(match.getId());
58	        }
59	    }
60	
61	    private static boolean equalsIgnoreCase(String a, String b) {
62	        return a == null ? b == null : a.equalsIgnoreCase(b);
63	    }
64	
65	    private static boolean equals(String a, String b) {
66	        return a == null ? b == null : a.equals(b);
67	    }
68	}
