399	            if (value >= 2000 && value <= 2099) {
400	                return "NSW";
401	            }
402	            if (value >= 3000 && value <= 3099) {
403	                return "VIC";
404	            }
405	            if (value >= 4000 && value <= 4099) {
406	                return "QLD";
407	            }
408	        }
409	        if ("Sydney".equals(this.city)) {
410	            return "NSW";
411	        }
412	        if ("Melbourne".equals(this.city)) {
413	            return "VIC";
414	        }
415	        if ("Brisbane".equals(this.city)) {
416	            return "QLD";
417	        }
418	        return "UNKNOWN";
419	    }
420	
421	    /**
422	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
423	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
424	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
425	     */
426	    @Transient
427	    public String getTimezone() {
428	        switch (getRegion()) {
429	            case "NSW":
430	                return "Australia/Sydney";
431	            case "VIC":
432	                return "Australia/Melbourne";
433	            case "QLD":
434	                return "Australia/Brisbane";
435	            default:
436	                return null;
437	        }
438	    }
439	
