13	final class OwnerEmail {
14	
15	    /**
16	     * A pragmatic "syntactically valid address" check: a non-empty local part, an
17	     * {@code @}, and a domain of at least two dot-separated labels — none of which may
18	     * contain whitespace or a further {@code @}.
19	     */
20	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
21	
22	    /**
23	     * Disposable email domains that owners may not register with. Compared lower-cased.
24	     */
25	    private static final Set<String> DISPOSABLE_DOMAINS =
26	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
27	
28	    private OwnerEmail() {
29	    }
30	
31	    /**
32	     * Normalize a supplied email. A {@code null} or blank value is treated as absent and
33	     * returns {@code null}. A present value must match {@link #EMAIL} and must not use a
34	     * disposable domain (see {@link #DISPOSABLE_DOMAINS}) or an
35	     * {@link InvalidEmailException} (400) is thrown; otherwise it is returned lower-cased.
36	     */
37	    static String normalize(String email) throws InvalidEmailException {
38	        if (email == null) {
39	            return null;
40	        }
41	        String trimmed = email.strip();
42	        if (trimmed.isEmpty()) {
43	            return null;
44	        }
45	        if (!EMAIL.matcher(trimmed).matches()) {
46	            throw new InvalidEmailException("Email is not a syntactically valid address: " + email);
47	        }
48	        String normalized = trimmed.toLowerCase(Locale.ROOT);
49	        String domain = normalized.substring(normalized.indexOf('@') + 1);
50	        if (DISPOSABLE_DOMAINS.contains(domain)) {
51	            throw new InvalidEmailException("Email domain is not permitted: " + email);
52	        }
53	        return normalized;
54	    }
55	}
